solutionCode.java:
public class Solution {
    public String reverse(String s) {
        char[] arr = s.toCharArray();
        int l = 0, r = arr.length - 1;
        while (l < r) {
            char t = arr[l]; arr[l++] = arr[r]; arr[r--] = t;
        }
        return new String(arr);
    }
}

