solutionCode.cpp:
#include <vector>
#include <unordered_map>
using namespace std;

vector<int> twoSum(vector<int>& nums, int target) {
    unordered_map<int,int> m;
    for (int i = 0; i < nums.size(); i++) {
        int comp = target - nums[i];
        if (m.count(comp)) return {m[comp], i};
        m[nums[i]] = i;
    }
    return {};
}
